#!/usr/bin/env node
/**
 * bundle.js — combines tsc's compiled CommonJS output (dist/*.js) into a
 * single main.js, which is what Obsidian's plugin folder actually expects
 * (main.js + manifest.json + optional styles.css/data.json — not a folder
 * of separate .js files requiring each other).
 *
 * Why this exists instead of esbuild: esbuild isn't installable in the
 * environment this was authored in (no network access to npm). This
 * script is a small, purpose-built substitute — not a general bundler,
 * just enough to combine OUR flat graph of simple tsc-emitted CommonJS
 * modules, which never do anything more exotic than
 * `const x = require("./relative")` at the top of a file.
 *
 * If esbuild (or any bundler) IS available when you're reading this,
 * prefer it — see the commented esbuild.config.mjs alternative below this
 * file for a drop-in replacement once `npm install esbuild` works.
 *
 * Usage: node scripts/bundle.js
 * (npm run build already runs `tsc` then this, in order.)
 */

const fs = require("fs");
const path = require("path");

const DIST_DIR = path.join(__dirname, "..", "dist");
const OUT_FILE = path.join(__dirname, "..", "main.js");
const ENTRY = "./main";

function readModules() {
	const files = fs.readdirSync(DIST_DIR).filter((f) => f.endsWith(".js"));
	const modules = {};
	for (const file of files) {
		const id = "./" + file.replace(/\.js$/, "");
		let content = fs.readFileSync(path.join(DIST_DIR, file), "utf8");
		// Only relative requires get rewritten to the local module registry.
		// External packages (obsidian, @codemirror/*) are left as real
		// require() calls, resolved by Node/Obsidian at runtime exactly as
		// they always were — this bundler only inlines OUR OWN modules.
		content = content.replace(/require\((["'])(\.\/[^"']+)\1\)/g, '__localRequire($1$2$1)');
		modules[id] = content;
	}
	return modules;
}

function bundle() {
	if (!fs.existsSync(DIST_DIR)) {
		console.error('dist/ not found — run "tsc -p tsconfig.json" first (or just `npm run build`, which does both steps).');
		process.exit(1);
	}
	const modules = readModules();
	if (!modules[ENTRY]) {
		console.error(`Entry module "${ENTRY}" not found in dist/ — expected dist/main.js from the TypeScript compile.`);
		process.exit(1);
	}

	let out = "";
	out += "/* AUTO-GENERATED — do not edit this file directly.\n";
	out += " * Source: src/*.ts — edit there and run `npm run build`.\n";
	out += " * Bundled by scripts/bundle.js (see that file for why a hand-\n";
	out += " * rolled bundler instead of esbuild). */\n";
	out += '"use strict";\n\n';
	out += "var __modules = {};\n";
	out += "var __cache = {};\n";
	out += "function __localRequire(id) {\n";
	out += "  if (__cache[id]) return __cache[id].exports;\n";
	out += "  var mod = { exports: {} };\n";
	out += "  __cache[id] = mod;\n";
	out += "  __modules[id](mod, mod.exports);\n";
	out += "  return mod.exports;\n";
	out += "}\n\n";

	for (const [id, content] of Object.entries(modules)) {
		out += `__modules[${JSON.stringify(id)}] = function (module, exports) {\n`;
		out += content;
		out += `\n};\n\n`;
	}

	out += `module.exports = __localRequire(${JSON.stringify(ENTRY)});\n`;

	fs.writeFileSync(OUT_FILE, out, "utf8");
	console.log(`Bundled ${Object.keys(modules).length} modules -> ${path.relative(process.cwd(), OUT_FILE)} (${out.length} bytes)`);
}

bundle();
